namespace functioncalls.plugin;

using ghidra.framework.options;
using ghidra.graph.viewer.options;
using ghidra.util;

public class FcgOptions : VisualGraphOptions {

	public static readonly string FUNCTION_NAME_TRUNCATION_KEY = "Truncate Function Name";
	public static readonly string FUNCTDION_NAME_TRUNCTION_DESCRIPTION =
		"Long function names will be truncated";

	private bool useTruncatedFunctionNames = true;

	public bool useTruncatedFunctionNames() {
		return useTruncatedFunctionNames;
	}

	public void setUseTruncatedFunctionNames(bool b) {
		this.useTruncatedFunctionNames = b;
	}

	/* @Override */
	public void registerOptions(Options options, HelpLocation help) {
		base.registerOptions(options, help);

		options.registerOption(FUNCTION_NAME_TRUNCATION_KEY, useTruncatedFunctionNames(), help,
			FUNCTDION_NAME_TRUNCTION_DESCRIPTION);
	}

	/* @Override */
	public void loadOptions(Options options) {
		useTruncatedFunctionNames =
			options.getBoolean(FUNCTION_NAME_TRUNCATION_KEY, useTruncatedFunctionNames);
	}
}
